'use client';

import React, { useState, useTransition } from 'react';
import { useRouter } from 'next/navigation';
import {
  createBatch,
  deleteBatch,
  createChecklistItem,
  toggleItemState,
  deleteChecklistItem,
  clearAllChecklistItems,
} from '../actions';
import { format, parse, differenceInHours } from 'date-fns';
import { Plus, X, Upload } from 'lucide-react';
import Tesseract from 'tesseract.js';

interface Batch {
  id: number;
  name: string;
}

interface Item {
  id: number;
  subitem: string;
  label: string;
  date: string;
  time: string;
  gap: string;
  time_ok: boolean;
  crm_ok: boolean;
  done: boolean;
}

export default function CrmChecklist({
  initialBatches,
  initialItems,
  selectedBatchId,
}: {
  initialBatches: Batch[];
  initialItems: Item[];
  selectedBatchId: number | null;
}) {
  const router = useRouter();
  const [, startTransition] = useTransition();
  const fileInputRef = React.useRef<HTMLInputElement>(null);
  const [isUploading, setIsUploading] = useState(false);

  // Selected batch state managed by URL usually, but we can do a push
  const handleBatchSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const val = e.target.value;
    if (val) {
      router.push(`/?batch=${val}`);
    } else {
      router.push('/');
    }
  };

  // Batches
  const [newBatchName, setNewBatchName] = useState(
    initialBatches.length > 0 ? initialBatches[0].name : 'JACKSON-0426CT REMINDER SEQUENCE'
  );

  const handleCreateBatch = async () => {
    if (!newBatchName.trim()) return;
    const res = await createBatch(newBatchName.trim());
    if (res.success && res.id) {
      router.push(`/?batch=${res.id}`);
    } else {
      alert(res.error || 'Failed to create batch');
    }
  };

  const handleDeleteBatch = async () => {
    if (!selectedBatchId) return;
    if (confirm('Delete this batch?')) {
      await deleteBatch(selectedBatchId);
      router.push('/');
    }
  };

  const handleClearAll = async () => {
    if (!selectedBatchId) return;
    if (confirm('Clear all items?')) {
      await clearAllChecklistItems(selectedBatchId);
      router.refresh();
    }
  };

  const handleCopyAll = () => {
    const text = initialItems
      .map(
        (i) =>
          `${i.done ? '[x]' : '[ ]'} ${i.subitem} - ${i.label} - ${i.date} ${i.time}`
      )
      .join('\n');
    navigator.clipboard.writeText(text);
    alert('Copied to clipboard');
  };

  // Checklist Adding
  const [subitem, setSubitem] = useState('');
  const [label, setLabel] = useState('Text Reminder');
  const [dateStr, setDateStr] = useState('');
  const [timeStr, setTimeStr] = useState('10:00');

  const computeGap = (prevItems: Item[], newDateStr: string, newTimeStr: string): string => {
    if (prevItems.length === 0) return '0hrs';

    const currentItem = prevItems[prevItems.length - 1]; 
    try {
      const formatStr = 'MMM d, yyyy h:mm a';
      const prevDate = parse(`${currentItem.date} ${currentItem.time}`, formatStr, new Date());
      const newDate = parse(`${newDateStr} ${newTimeStr}`, formatStr, new Date());

      const diffHoursStr = Math.abs(differenceInHours(newDate, prevDate));
      if (isNaN(diffHoursStr)) return '0hrs';

      if (diffHoursStr < 24) {
        return `${diffHoursStr}hrs`;
      }
      const days = Math.floor(diffHoursStr / 24);
      const hours = diffHoursStr % 24;
      return `${diffHoursStr}hrs / ${days}d ${hours}hrs`;
    } catch {
      return '0hrs';
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!selectedBatchId) {
      alert('Select or create a batch first');
      return;
    }

    setIsUploading(true);
    try {
      const { data: { text } } = await Tesseract.recognize(file, 'eng');

      const lines = text.split('\n').filter(Boolean);
      const currentItems = [...initialItems];

      for (const line of lines) {
        // Look for typical CRM Checklist sequences in the text
        const match = line.match(/(.*?)(Call Reminder|Text Reminder|Email Reminder)?\s*([A-Z][a-z]{2}\s+\d{1,2},\s+\d{4})\s*(\d{1,2}:\d{2}\s*[AP]M)/i);
        if (match) {
          let rawSubitem = match[1].trim();
          let rawLabel = match[2]?.trim() || 'Text Reminder';
          let rawDate = match[3].trim(); 
          let rawTime = match[4].trim(); 

          rawSubitem = rawSubitem.replace(/^[^a-zA-Z0-9]+/, '');

          const gap = computeGap(currentItems, rawDate, rawTime);

          await createChecklistItem({
            batch_id: selectedBatchId,
            subitem: rawSubitem || 'Unknown',
            label: rawLabel,
            date: rawDate,
            time: rawTime,
            gap,
          });

          currentItems.push({
             id: Date.now(), 
             subitem: rawSubitem,
             label: rawLabel,
             date: rawDate,
             time: rawTime,
             gap,
             done: false,
             time_ok: false,
             crm_ok: false
          } as Item);
        }
      }

      router.refresh();
    } catch (err) {
      console.error(err);
      alert('Error parsing image. Ensure the image is highly legible.');
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBatchId) return alert('Select or create a batch first');
    if (!subitem || !dateStr || !timeStr) return alert('Fill required fields');

    const formattedDate = format(new Date(dateStr), 'MMM d, yyyy');
    let formattedTime = timeStr;
    try {
      const [hour, min] = timeStr.split(':');
      let h = parseInt(hour, 10);
      const ampm = h >= 12 ? 'PM' : 'AM';
      h = h % 12 || 12;
      formattedTime = `${h}:${min} ${ampm}`;
    } catch {}

    const gap = computeGap(initialItems, formattedDate, formattedTime);

    await createChecklistItem({
      batch_id: selectedBatchId,
      subitem,
      label,
      date: formattedDate,
      time: formattedTime,
      gap,
    });

    setSubitem('');
    // Optionally keep date/time or reset
  };

  const handleToggle = async (id: number, field: 'done' | 'time_ok' | 'crm_ok', currentState: boolean) => {
    startTransition(async () => {
      await toggleItemState(id, field, currentState);
      router.refresh(); // Rely on Next.js mutations
    });
  };

  const handleDeleteItem = async (id: number) => {
    startTransition(async () => {
      await deleteChecklistItem(id);
      router.refresh();
    });
  };

  const completedCount = initialItems.filter((i) => i.done).length;
  const totalCount = initialItems.length;
  const percent = totalCount === 0 ? 0 : Math.round((completedCount / totalCount) * 100);

  return (
    <div className="panel">
      <div className="panel-header">Checklist</div>

      <div className="form-group">
        <label>Batch Name</label>
        <div className="input-row">
          <input
            type="text"
            className="flex-grow"
            value={newBatchName}
            onChange={(e) => setNewBatchName(e.target.value)}
          />
          <button className="btn primary" onClick={handleCreateBatch}>
            Save Batch
          </button>
          <button className="btn" onClick={() => setNewBatchName('')}>
            New Batch
          </button>
        </div>
      </div>

      <div className="form-group">
        <label>Load Saved Batch</label>
        <div className="input-row">
          <select className="flex-grow" value={selectedBatchId || ''} onChange={handleBatchSelect}>
            <option value="" disabled>Select a batch</option>
            {initialBatches.map((b) => (
              <option key={b.id} value={b.id}>
                {b.name}
              </option>
            ))}
          </select>
          <button className="btn" onClick={handleDeleteBatch}>
            Delete Batch
          </button>
        </div>
      </div>

      <div className="progress-container">
        <div className="progress-bar-track">
          <div className="progress-bar-fill" style={{ width: `${percent}%` }}></div>
        </div>
        <div className="progress-stats">
          <span>{completedCount} of {totalCount} completed</span>
          <span>{percent}%</span>
        </div>
      </div>

      <div className="toolbar">
        <input 
          type="file" 
          accept="image/*" 
          ref={fileInputRef} 
          style={{ display: 'none' }} 
          onChange={handleFileUpload}
        />
        <button className="btn" onClick={() => fileInputRef.current?.click()} style={{ display: 'flex', alignItems: 'center', gap: '6px' }} disabled={isUploading}>
          <Upload size={14} /> {isUploading ? 'Analyzing...' : 'Upload Image'}
        </button>
        <button className="btn" onClick={() => alert('Exporting Excel...')}>Export Excel</button>
        <button className="btn" onClick={() => alert('Exporting PDF...')}>Export PDF</button>
        <button className="btn" onClick={handleCopyAll}>Copy All</button>
        <button className="btn" onClick={handleClearAll}>Clear All</button>
      </div>

      {/* List Container */}
      <div className="checklist-container">
        <div className="checklist-header">
          <div className="centered">Done</div>
          <div>Subitem</div>
          <div>Label</div>
          <div>Date</div>
          <div>Time</div>
          <div>Gap</div>
          <div className="centered">Time<br/>OK</div>
          <div className="centered">CRM<br/>OK</div>
          <div className="centered">Action</div>
        </div>

        {initialItems.length === 0 ? (
          <div className="empty-state">No items in this batch. Ad one below.</div>
        ) : (
          initialItems.map((item) => {
            const labelClass = item.label.toLowerCase().includes('call') ? 'call' : item.label.toLowerCase().includes('email') ? 'email' : 'text';
            return (
              <div key={item.id} className={`checklist-row ${item.done ? 'is-done' : ''}`}>
                <div className="centered">
                  <input
                    type="checkbox"
                    className="custom-checkbox"
                    checked={item.done}
                    onChange={() => handleToggle(item.id, 'done', item.done)}
                  />
                </div>
                <div className="subitem-text">{item.subitem}</div>
                <div>
                  <span className={`pill ${labelClass}`}>{item.label}</span>
                </div>
                <div>{item.date}</div>
                <div>{item.time}</div>
                <div className="gap-text">{item.gap}</div>
                <div className="centered">
                  <input
                    type="checkbox"
                    className="custom-checkbox"
                    checked={item.time_ok}
                    onChange={() => handleToggle(item.id, 'time_ok', item.time_ok)}
                  />
                </div>
                <div className="centered">
                  <input
                    type="checkbox"
                    className="custom-checkbox"
                    checked={item.crm_ok}
                    onChange={() => handleToggle(item.id, 'crm_ok', item.crm_ok)}
                  />
                </div>
                <div className="centered">
                  <button className="btn-delete" onClick={() => handleDeleteItem(item.id)}>
                    <X size={14} />
                  </button>
                </div>
              </div>
            );
          })
        )}

        {/* Add Row Form Container */}
        <form className="add-row" onSubmit={handleAddItem}>
          <div className="centered-icon">+</div>
          <div>
            <input
              type="text"
              placeholder="Subitem name"
              value={subitem}
              onChange={(e) => setSubitem(e.target.value)}
              required
            />
          </div>
          <div>
            <select value={label} onChange={(e) => setLabel(e.target.value)}>
              <option value="Text Reminder">Text Reminder</option>
              <option value="Call Reminder">Call Reminder</option>
              <option value="Email Reminder">Email Reminder</option>
            </select>
          </div>
          <div>
            <input 
              type="date" 
              value={dateStr} 
              onChange={(e) => setDateStr(e.target.value)} 
              required 
            />
          </div>
          <div>
            <input 
              type="time" 
              value={timeStr} 
              onChange={(e) => setTimeStr(e.target.value)} 
              required 
            />
          </div>
          <div className="centered">-</div>
          <div className="centered" style={{ gridColumn: 'span 3', display: 'flex', justifyContent: 'flex-end', paddingRight: '12px' }}>
            <button type="submit" className="btn primary icon" style={{ borderRadius: '50%', width: '28px', height: '28px', padding: 0 }}>
              <Plus size={16} />
            </button>
          </div>
        </form>
      </div>

    </div>
  );
}
